alter policy order_insert on print.orders with check(status='draft' and quote_cents is null and exists(select 1 from print.memberships m where m.company_id=orders.company_id and m.user_id=(select auth.uid())) and exists(select 1 from print.products p where p.company_id=orders.company_id and p.id=orders.product_id and p.active) and exists(select 1 from storage.objects o where o.bucket_id='print-artworks' and o.name=orders.artwork_path));
